"pre": "ข้อมูลที่ใช้ (N = เลขชุดของคุณ 1–8)\n• ใบสั่งซื้อที่ชุดคุณสร้างใน PUR-04\n• คลังรับเข้า: RN-WH-RM RN-คลังวัตถุดิบ\n• เลขล็อตผู้ขาย: RN-SKLN-6910-01 (ขมิ้นชัน) · RN-SKLN-6910-02 (ฟ้าทะลายโจร)\nข้อมูลแต่ละชุด\n• ชุด 1: ใบสั่งซื้อจาก PR2026-0003 · ล็อตผู้ขาย RN-SKL1-6910-01 / RN-SKL1-6910-02\n• ชุด 2: ใบสั่งซื้อจาก PR2026-0004 · ล็อตผู้ขาย RN-SKL2-6910-01 / RN-SKL2-6910-02\n• ชุด 3: ใบสั่งซื้อจาก PR2026-0005 · ล็อตผู้ขาย RN-SKL3-6910-01 / RN-SKL3-6910-02\n• ชุด 4: ใบสั่งซื้อจาก PR2026-0006 · ล็อตผู้ขาย RN-SKL4-6910-01 / RN-SKL4-6910-02\n• ชุด 5: ใบสั่งซื้อจาก PR2026-0007 · ล็อตผู้ขาย RN-SKL5-6910-01 / RN-SKL5-6910-02\n• ชุด 6: ใบสั่งซื้อจาก PR2026-0008 · ล็อตผู้ขาย RN-SKL6-6910-01 / RN-SKL6-6910-02\n• ชุด 7: ใบสั่งซื้อจาก PR2026-0009 · ล็อตผู้ขาย RN-SKL7-6910-01 / RN-SKL7-6910-02\n• ชุด 8: ใบสั่งซื้อจาก PR2026-0010 · ล็อตผู้ขาย RN-SKL8-6910-01 / RN-SKL8-6910-02\nข้อควรรู้\n• อย่าเลือกคลัง WH-RM (ปิดใช้งานแล้ว)\n• วันผลิต/วันหมดอายุ ให้กดเลือกจากปฏิทิน\n• รายการตรวจรับ ติ๊กข้อที่มี * ให้ครบ (ข้อ COA \"ถ้ามี\" ไม่บังคับ)\n• หลังรับสินค้า ระบบสร้างใบแจ้งหนี้ฉบับร่างให้เอง (ใช้ต่อใน ACC-02)",
