"pre": "ข้อมูลที่ใช้ (N = เลขชุดของคุณ 1–8)\n• เลขที่ล็อต RN-INVN-6910-01 (พิมพ์เอง ไม่กด \"สร้าง\")\n• สินค้า RN-RM-003 ขิงผง · คลัง RN-คลังวัตถุดิบ · 2 กก. × 120.00 บาท\n• วันผลิต 1 ต.ค. 2569 · วันหมดอายุ 30 ก.ย. 2571\nข้อมูลแต่ละชุด\n• ชุด 1: RN-INV1-6910-01\n• ชุด 2: RN-INV2-6910-01\n• ชุด 3: RN-INV3-6910-01\n• ชุด 4: RN-INV4-6910-01\n• ชุด 5: RN-INV5-6910-01\n• ชุด 6: RN-INV6-6910-01\n• ชุด 7: RN-INV7-6910-01\n• ชุด 8: RN-INV8-6910-01\nข้อควรรู้\n• ล็อตนี้ใช้ต่อใน INV-03, INV-06, INV-07 และ INV-08 (ตัดจำหน่าย) — อย่าส่งให้ QC อนุมัติ\n• อย่าเลือกคลัง WH-RM (ปิดใช้งานแล้ว)",
