"menu": "คลังสินค้า › คลังสินค้า",
"pre": "ข้อมูลที่ใช้ (N = เลขชุดของคุณ 1–8)\n• คลังใหม่ RN-WH-TN ชื่อ RN-ชั้นพักวัตถุดิบชุด N ประเภท วัตถุดิบ\n• รหัสซ้ำที่ใช้ลอง: RN-WH-RM\n• คลังที่เปิดดู: RN-WH-RM RN-คลังวัตถุดิบ\nข้อมูลแต่ละชุด\n• ชุด 1: RN-WH-T1 RN-ชั้นพักวัตถุดิบชุด 1\n• ชุด 2: RN-WH-T2 RN-ชั้นพักวัตถุดิบชุด 2\n• ชุด 3: RN-WH-T3 RN-ชั้นพักวัตถุดิบชุด 3\n• ชุด 4: RN-WH-T4 RN-ชั้นพักวัตถุดิบชุด 4\n• ชุด 5: RN-WH-T5 RN-ชั้นพักวัตถุดิบชุด 5\n• ชุด 6: RN-WH-T6 RN-ชั้นพักวัตถุดิบชุด 6\n• ชุด 7: RN-WH-T7 RN-ชั้นพักวัตถุดิบชุด 7\n• ชุด 8: RN-WH-T8 RN-ชั้นพักวัตถุดิบชุด 8\nข้อควรรู้\n• ห้ามลบหรือแก้คลังจริงของโรงงาน (RN-WH-RM, RN-WH-FG, RN-WH-QC, WH-…) — กด \"ลบ\" ได้เฉพาะคลัง RN-WH-TN ของชุดคุณ",
