"กด \"เพิ่มคลัง\" เลือก \"ประเภทคลัง\" = วัตถุดิบ พิมพ์ \"รหัสคลัง *\" RN-WH-RM (รหัสที่มีอยู่แล้ว) และ \"ชื่อคลัง *\"",
