"pre": "ข้อมูลที่ใช้ (N = เลขชุดของคุณ 1–8)\n• ผลทดสอบขมิ้นชันผงของชุดคุณจาก QC-02\nข้อมูลแต่ละชุด\n• ชุด 1: ขมิ้นชันผง ล็อตผู้ขาย RN-SKL1-6910-01\n• ชุด 2: ขมิ้นชันผง ล็อตผู้ขาย RN-SKL2-6910-01\n• ชุด 3: ขมิ้นชันผง ล็อตผู้ขาย RN-SKL3-6910-01\n• ชุด 4: ขมิ้นชันผง ล็อตผู้ขาย RN-SKL4-6910-01\n• ชุด 5: ขมิ้นชันผง ล็อตผู้ขาย RN-SKL5-6910-01\n• ชุด 6: ขมิ้นชันผง ล็อตผู้ขาย RN-SKL6-6910-01\n• ชุด 7: ขมิ้นชันผง ล็อตผู้ขาย RN-SKL7-6910-01\n• ชุด 8: ขมิ้นชันผง ล็อตผู้ขาย RN-SKL8-6910-01\nใครทำ (ลงนามตามลำดับ คนละคน)\n• 1) ผู้วิเคราะห์ QC → 2) หัวหน้า QC → 3) หัวหน้า QA กด \"ปล่อยผ่าน\" → 4) คลังกดปล่อยเข้าคลัง\nข้อควรรู้\n• หลังส่งทบทวน ผู้วิเคราะห์ยังเห็นปุ่มอนุมัติ ไม่ต้องกด\n• ปล่อยเข้าคลังเฉพาะใบรับสินค้าของชุดคุณ",
