"ตรวจ \"ขนาดชุดผลิต\" และรายการวัตถุดิบ/บรรจุภัณฑ์กับสูตรจริง — สูตร \"อนุมัติแล้ว\" มีข้อความ \"สูตรนี้อนุมัติแล้ว — แก้ไขวัตถุดิบไม่ได้ …\" และไม่มีไอคอนแก้ไข/ลบในตาราง",
"กดปุ่ม \"⋯\" (การดำเนินการเพิ่มเติม) › \"คัดลอก BOM\" กรอก \"รหัส BOM ใหม่ *\" \"เวอร์ชัน\" และ \"ชื่อ BOM\" แล้วกด \"คัดลอก BOM\"",
"ระบบเปิดสูตรใหม่สถานะ \"ร่าง\" — ดูว่าตารางมีไอคอนดินสอ (แก้ไขจำนวน) และถังขยะ (นำรายการออก) แก้รายการที่ทบทวนแล้วต้องเปลี่ยน (ถ้ามี)",
