"pre": "ข้อมูลที่ใช้ (N = เลขชุดของคุณ 1–8)\n• สูตร RN-BOM-FG1N-V2 (ตั้งค่าแล้วจาก PRD-02)\n• หมายเลขรุ่นการผลิต RN-PRDN-6910-01 · จำนวนที่วางแผน 20 ขวด · วันที่เริ่ม/สิ้นสุดตามแผน = วันที่ทดสอบ / +2 วัน\n• เจ้าหน้าที่: พนักงานผลิตของชุด = ผู้ปฏิบัติงาน · เจ้าหน้าที่ QA = ผู้ตรวจสอบ QA\n• ของในคลังที่ต้องปล่อยแล้ว (ใบสั่งผลิต 20 ขวด): ขมิ้นชันผง RN-RM-001 ≥ 1 กก. (ล็อตจาก PUR-05/QC-03 ของชุดคุณ) · แคปซูลเปล่า RN-PK-001 ≥ 2,000 ชิ้น · ขวด RN-PK-002 ≥ 25 ขวด (เตรียมไว้แล้วในคลัง RN-WH-RM: แคปซูล RN-PK001-6910-P1 · ขวด RN-PK002-6910-P1 · ถ้าล็อตขมิ้นชันของชุดคุณยังไม่ปล่อย ใช้ RN-RM001-6910-P1 ได้)\nข้อมูลแต่ละชุด\n• ชุด 1: สูตร RN-BOM-FG11-V2 · รุ่นผลิต RN-PRD1-6910-01\n• ชุด 2: สูตร RN-BOM-FG12-V2 · รุ่นผลิต RN-PRD2-6910-01\n• ชุด 3: สูตร RN-BOM-FG13-V2 · รุ่นผลิต RN-PRD3-6910-01\n• ชุด 4: สูตร RN-BOM-FG14-V2 · รุ่นผลิต RN-PRD4-6910-01\n• ชุด 5: สูตร RN-BOM-FG15-V2 · รุ่นผลิต RN-PRD5-6910-01\n• ชุด 6: สูตร RN-BOM-FG16-V2 · รุ่นผลิต RN-PRD6-6910-01\n• ชุด 7: สูตร RN-BOM-FG17-V2 · รุ่นผลิต RN-PRD7-6910-01\n• ชุด 8: สูตร RN-BOM-FG18-V2 · รุ่นผลิต RN-PRD8-6910-01\nใครทำ\n• คนที่ 1 (หัวหน้าฝ่ายผลิต): ขั้น 1–7, 10–11 · คนที่ 2 (คลัง): ขั้น 8–9\nข้อควรรู้\n• ใบสั่งผลิตใหม่ขอเบิกวัตถุดิบตามสูตรให้คลังอัตโนมัติ — ไม่ต้องกดขอเบิก\n• ถ้าขึ้น \"วัตถุดิบไม่เพียงพอ\" ตอนคลังอนุมัติ ให้บันทึกผลพร้อมภาพแล้วแจ้งทีม BMS (ล็อตที่หมดอายุไม่นับเป็นของพร้อมใช้)",
