"pre": "ข้อมูลที่ใช้ (N = เลขชุดของคุณ 1–8)\n• ใบสั่งผลิต RN-PRDN-6910-01 จาก PRD-03 ของชุดคุณ สถานะ \"ปล่อยแล้ว\" ยังไม่เคยบันทึกเคลียร์ไลน์\n• เหตุผลปฏิเสธ: \"พบฉลากรุ่นก่อนติดที่โต๊ะชั่ง ให้เอาออกแล้วบันทึกใหม่\"\nข้อมูลแต่ละชุด\n• ชุด 1: ใบสั่งผลิตรุ่น RN-PRD1-6910-01\n• ชุด 2: ใบสั่งผลิตรุ่น RN-PRD2-6910-01\n• ชุด 3: ใบสั่งผลิตรุ่น RN-PRD3-6910-01\n• ชุด 4: ใบสั่งผลิตรุ่น RN-PRD4-6910-01\n• ชุด 5: ใบสั่งผลิตรุ่น RN-PRD5-6910-01\n• ชุด 6: ใบสั่งผลิตรุ่น RN-PRD6-6910-01\n• ชุด 7: ใบสั่งผลิตรุ่น RN-PRD7-6910-01\n• ชุด 8: ใบสั่งผลิตรุ่น RN-PRD8-6910-01\nใครทำ\n• คนที่ 1 (พนักงานผลิต): ขั้น 1–3, 5 · คนที่ 2 (หัวหน้าฝ่ายผลิต): ขั้น 4, 6–8\nข้อควรรู้\n• ทำข้อนี้ก่อน PRD-05 — PRD-05 บันทึกเคลียร์ไลน์ใหม่หลังถูกปฏิเสธ",
