"expect": "ก่อนทำครบ: \"เปลี่ยนเป็น เสร็จสิ้น ไม่ได้ — ยังทำขั้นตอนไม่ครบ\" 1. ยังไม่ได้บันทึกการตรวจสอบผลิตภัณฑ์สำเร็จรูป 2. ยังไม่ได้บันทึกผลผลิตสินค้าสำเร็จรูป · สร้างการตรวจแล้ว \"สร้างการตรวจสินค้าสำเร็จรูปเรียบร้อย\" · ผู้สุ่มยืนยันเอง ระบบแจ้ง \"ผู้ตรวจต้องเป็นคนละคนกับผู้สุ่มตัวอย่าง — GMP บังคับให้มีการตรวจสอบโดยอิสระ\" · หัวหน้า QC ยืนยันแล้ว \"บันทึกแล้ว ยืนยันผลตรวจ: ผ่าน\" 15/15 · ผลผลิตขึ้น \"บันทึกผลผลิตสำเร็จ สร้างล็อตสินค้าสำเร็จรูปในคลังแล้ว\" ผลได้ 100 % · เสร็จสิ้นแล้วสถานะ \"เสร็จสิ้น\" จำนวนจริง 20 ผลผลิต 100 % และมีปุ่ม \"เปลี่ยนเป็น ปิดแล้ว\"",
"note": "ล็อตสินค้าสำเร็จรูปเข้าคลังแบบกักกันพร้อมใบรับสินค้า (GRN) รอ QC — ปล่อยใน PRD-11 · ถ้าผลได้ต่ำกว่าเป้าตามสูตร ให้บันทึกสิ่งที่ระบบแสดง",
