"หัวหน้าคลังเปิด คลังสินค้า › ใบเบิกวัตถุดิบ แท็บ \"เบิกนอก BOM\" คลิกใบสั่งผลิตของคำขอที่ \"รอคลังจ่าย\" ตรวจวัตถุดิบ ปริมาณ และคงเหลือในคลัง",
"กด \"ปล่อยของ (ตัดสต็อก)\" แล้วกลับไปดู \"ประวัติการเบิกเพิ่ม\" ของใบสั่งผลิต"
