"pre": "ข้อมูลที่ใช้ (N = เลขชุดของคุณ 1–8)\n• หน่วยงานและตำแหน่งที่ชุดคุณสร้างใน HR-01\n• พนักงาน 3 คน: ต่อท้ายนามสกุลด้วย \"ชุดที่ N\"\n• พนักงานพ้นสภาพ: RN-E19-N \"RN-ทดสอบพ้นสภาพ ชุดที่ N\"\n• ไฟล์รูป: RN-รูปพนักงานการ์ตูน.png (ทีม BMS ส่งให้)\nข้อมูลแต่ละชุด\n• ชุด 1: พนักงานพ้นสภาพ RN-E19-1 · นามสกุลพนักงานใหม่ต่อท้าย \"ชุดที่ 1\"\n• ชุด 2: พนักงานพ้นสภาพ RN-E19-2 · นามสกุลพนักงานใหม่ต่อท้าย \"ชุดที่ 2\"\n• ชุด 3: พนักงานพ้นสภาพ RN-E19-3 · นามสกุลพนักงานใหม่ต่อท้าย \"ชุดที่ 3\"\n• ชุด 4: พนักงานพ้นสภาพ RN-E19-4 · นามสกุลพนักงานใหม่ต่อท้าย \"ชุดที่ 4\"\n• ชุด 5: พนักงานพ้นสภาพ RN-E19-5 · นามสกุลพนักงานใหม่ต่อท้าย \"ชุดที่ 5\"\n• ชุด 6: พนักงานพ้นสภาพ RN-E19-6 · นามสกุลพนักงานใหม่ต่อท้าย \"ชุดที่ 6\"\n• ชุด 7: พนักงานพ้นสภาพ RN-E19-7 · นามสกุลพนักงานใหม่ต่อท้าย \"ชุดที่ 7\"\n• ชุด 8: พนักงานพ้นสภาพ RN-E19-8 · นามสกุลพนักงานใหม่ต่อท้าย \"ชุดที่ 8\"\nข้อควรรู้\n• อัปโหลดรูปได้หลังกดบันทึกพนักงานแล้ว",
